test('every popup paints the kit floating surface', async () => {
  const offenders = [];
  for (const file of await guiSources()) {
    const src = stripComments(await readFile(file, 'utf8'));
    if (!/:\s*public\s+(?:PopupWindow|wxPopupWindow|wxPopupTransientWindow)\b|:\s*(?:PopupWindow|wxPopupWindow|wxPopupTransientWindow)\s*\(|new\s+(?:PopupWindow|wxPopupWindow)\(/.test(src)) continue;
    if (/DrawRoundedRectangle\([^;]*,\s*0\s*\)\s*;|\*wxLIGHT_GREY/.test(src))
      offenders.push(path.relative(gui(), file).replace(/\\/g, '/'));
  }
  assert.deepEqual(offenders, [], 'popups must not paint square frames or legacy grey plates');
  const cal = stripComments(await read('ChangelogDialog.cpp'));
  const popover = cal.slice(cal.indexOf('class ChangelogCalendarPopup'), cal.indexOf('class ', cal.indexOf('class ChangelogCalendarPopup') + 10));
  assert.match(popover, /MD3::Role::OutlineVariant/, 'the calendar popover has the kit hairline');
  assert.match(popover, /MD3::Metrics::\w*radius|WindowShadow/, 'and the kit radius and elevation');
});

test('the native token mirror equals the vendored kit, role by role', async () => {
  const tokens = await read('Widgets', 'MD3Tokens.hpp');
  const css = await readFile(path.join(repoDir, 'ui-md3', 'design-system', 'tokens', 'colors.css'), 'utf8');
  const kit = (sel) => Object.fromEntries([...css.slice(css.indexOf(sel)).split('}')[0]
    .matchAll(/--md-([\w-]+):(#[0-9a-f]{6})/gi)].map((m) => [m[1], m[2].toLowerCase()]));
  const native = (ns) => {
    const b = tokens.slice(tokens.indexOf(`namespace ${ns} {`), tokens.indexOf(`} // namespace ${ns}`));
    return Object.fromEntries([...b.matchAll(/inline const wxColour (\w+)\{"(#[0-9a-f]{6})"\}/gi)].map((m) => [m[1], m[2].toLowerCase()]));
  };
  const map = { surface: 'surface', scLowest: 'sc-lowest', scLow: 'sc-low', sc: 'sc', scHigh: 'sc-high', scHighest: 'sc-highest',
    onSurface: 'on-surface', onSurfaceVariant: 'on-surface-variant', outline: 'outline', outlineVariant: 'outline-variant' };
  for (const [ns, sel] of [['Light', '[data-theme="light"]'], ['Dark', '[data-theme="dark"]']])
    for (const [n, k] of Object.entries(map))
      assert.equal(native(ns)[n], kit(sel)[k], `${ns}::${n} must equal the kit --md-${k}`);
});

